import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { isDatabaseCapabilityEnabled } from "../../capabilities.js";
import { AUTOGENERATED_DIR, PACKAGE_JSON } from "../../constants.js";
import { dependsOnOf } from "../../dependency-graph.js";
import { formatCount } from "../../formatting.js";
import { findProjectRoot } from "../../paths.js";
import { discoverResourcesFromRoot } from "../../services.js";
import { databaseResourceNames, evaluateSharedPlatformPostgres, namesSharedPlatformPostgres, } from "../../shared-platform-postgres.js";
import { fileMigrations, START_SCRIPTS } from "./migrations.js";
import { readText } from "./shared.js";
const PRISMA_MAJOR = 7;
function packageJson(resourcePath) {
    try {
        const value = JSON.parse(readFileSync(join(resourcePath, PACKAGE_JSON), "utf-8"));
        return value && typeof value === "object" ? value : {};
    }
    catch {
        return {};
    }
}
function dependencyMajor(value) {
    if (typeof value !== "string")
        return undefined;
    const match = value.match(/(?:^|[^0-9])(\d+)(?:\.|$)/);
    return match ? Number(match[1]) : undefined;
}
function prismaSchemaFindings(path) {
    const raw = readText(path);
    if (raw === undefined)
        return ["missing prisma/schema.prisma"];
    const text = raw
        .replace(/\/\*[\s\S]*?\*\//g, "")
        .split("\n")
        .map((line) => (line.trimStart().startsWith("//") ? "" : line))
        .join("\n");
    const findings = [];
    const datasource = text.match(/datasource\s+\w+\s*\{([^}]*)\}/)?.[1] ?? "";
    if (!/provider\s*=\s*["']postgresql["']/.test(datasource))
        findings.push("schema provider is not postgresql");
    if (/\b(?:url|directUrl)\s*=/.test(text))
        findings.push("schema still declares url/directUrl");
    return findings;
}
function prismaConfigFindings(resourcePath) {
    const generated = join(resourcePath, AUTOGENERATED_DIR, "prisma.config.autogenerated.ts");
    const candidates = [join(resourcePath, "prisma.config.ts"), generated];
    const path = candidates.find((candidate) => existsSync(candidate));
    if (!path)
        return ["missing prisma.config.ts or generated Prisma config"];
    const text = readText(path) ?? "";
    const datasource = text.match(/datasource\s*:\s*\{([^}]*)\}/)?.[1] ?? "";
    if (!/url\s*:\s*(?:env\(["']DATABASE_URL["']\)|process\.env\.DATABASE_URL)\s*,?/.test(datasource)) {
        return ['Prisma config datasource.url is not env("DATABASE_URL")'];
    }
    return [];
}
/** Enforces the Prisma 7 project contract before `flisk up` can run. */
export function checkPrismaConsistency(projectRoot = findProjectRoot() ?? process.cwd(), resources = discoverResourcesFromRoot(projectRoot), options) {
    const prismaResources = resources.filter((resource) => resource.config?.featuresEnabled?.includes("prisma"));
    const findings = [];
    const migrators = resources.filter((resource) => resource.config?.appType === "migrator");
    const databaseNames = databaseResourceNames(resources);
    for (const resource of resources) {
        const legacyFeatures = resource.config?.features;
        if (Array.isArray(legacyFeatures) &&
            legacyFeatures.includes("prisma") &&
            !resource.config?.featuresEnabled?.includes("prisma")) {
            findings.push(`${resource.name}: use featuresEnabled, not features, for Prisma`);
        }
    }
    if (prismaResources.length === 0) {
        return findings.length === 0
            ? {
                name: "Prisma 7 consistency",
                didPass: true,
                isSkipped: true,
                message: "No resources enable Prisma; Prisma consistency checks were skipped",
            }
            : {
                name: "Prisma 7 consistency",
                didPass: false,
                message: `${formatCount(findings.length, "Prisma consistency error")}:\n    ${findings.join("\n    ")}`,
                fix: "Use featuresEnabled to opt into the validated Prisma 7 shape",
            };
    }
    for (const resource of prismaResources) {
        const dependencies = packageJson(resource.path).dependencies;
        const devDependencies = packageJson(resource.path).devDependencies;
        const packages = { ...(devDependencies ?? {}), ...(dependencies ?? {}) };
        const prismaMajor = dependencyMajor(packages.prisma);
        const clientMajor = dependencyMajor(packages["@prisma/client"]);
        if (prismaMajor === undefined || clientMajor === undefined)
            findings.push(`${resource.name}: prisma and @prisma/client are required`);
        else if (prismaMajor !== clientMajor || prismaMajor !== PRISMA_MAJOR)
            findings.push(`${resource.name}: prisma packages must both be major 7`);
        findings.push(...prismaSchemaFindings(join(resource.path, "prisma", "schema.prisma")).map((finding) => `${resource.name}: ${finding}`));
        findings.push(...prismaConfigFindings(resource.path).map((finding) => `${resource.name}: ${finding}`));
        const appType = resource.config?.appType ?? resource.type;
        if (appType === "migrator") {
            const postgresDependency = dependsOnOf(resource.config).some((name) => namesSharedPlatformPostgres(name, databaseNames));
            if (!postgresDependency)
                findings.push(`${resource.name}: migrator must depend on postgres, database-management or a database resource`);
        }
        else {
            // The API reaches Postgres only through its migrator, and that migrator must start Postgres (checked above).
            const migratorDependency = dependsOnOf(resource.config).some((name) => migrators.some((candidate) => candidate.name === name));
            if (!migratorDependency)
                findings.push(`${resource.name}: API must depend on its Prisma migrator, which depends on postgres or database-management`);
            const scripts = packageJson(resource.path).scripts;
            if (Object.entries(scripts ?? {}).some(([name, command]) => START_SCRIPTS.has(name) &&
                typeof command === "string" &&
                /prisma\s+migrate/.test(command))) {
                findings.push(`${resource.name}: API start script must not run prisma migrate`);
            }
            const dockerfile = join(resource.path, resource.config?.dockerfile ?? "Dockerfile");
            if (fileMigrations(dockerfile, true)) {
                findings.push(`${resource.name}: API image/startup must not run Prisma migrations`);
            }
        }
    }
    if (isDatabaseCapabilityEnabled(projectRoot, options) &&
        prismaResources.length > 0 &&
        !evaluateSharedPlatformPostgres(projectRoot, resources, options).willStart) {
        findings.push("shared platform Postgres will not start for the Prisma resources");
    }
    return findings.length === 0
        ? {
            name: "Prisma 7 consistency",
            didPass: true,
            message: "Prisma resources use the validated Prisma 7 shape",
        }
        : {
            name: "Prisma 7 consistency",
            didPass: false,
            message: `${formatCount(findings.length, "Prisma consistency error")}:\n    ${findings.join("\n    ")}`,
            fix: "Use Prisma 7 packages and config, put migrations in a migrator, and make the API depend on that migrator",
        };
}
